<script setup lang="ts">
import { computed,nextTick,onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import type { PDFDocumentProxy } from 'pdfjs-dist'
import { loadPdf,exportAnnotated } from '../lib/pdf'
import { getDocument,saveDocument,downloadBlob } from '../lib/storage'
import type { LocalDocument,Annotation } from '../types'
import {useBackendStore} from '../stores/backend'
import { useResearchStore } from '../stores/research'
import PdfPage from '../components/PdfReadingPage.vue'
import Markdown from '../components/ResearchMarkdown.vue'
import SelectionToolbar from '../components/ReaderSelectionToolbar.vue'
import ReaderAssistant from '../components/ReaderAssistant.vue'
import type {ReadingRequest} from '../lib/readerContext'
import type {BackendMessage} from '../services/backendApi'
import {useAssistantWidth} from '../composables/useAssistantWidth'
import {findPageMatches} from '../lib/reading'
import Icon from '../components/AppIcon.vue'
import {compactAuthors,readerLayoutState,type ReaderLayout} from '../lib/readerPresentation'
import Brand from '../components/BrandMark.vue'

import 'pdfjs-dist/web/pdf_viewer.css'
const route=useRoute(),router=useRouter(),store=useResearchStore(),backend=useBackendStore()
const readerWorkspace=ref('default'),showLegacy=ref(false)
const legacyAnnotations=computed(()=>doc.value?.annotations.filter(a=>!a.workspaceId&&(!a.ownerId||a.ownerId===backend.user?.id))||[])
const visibleAnnotations=computed(()=>doc.value?.annotations.filter(a=>((a.workspaceId===readerWorkspace.value)||(!a.workspaceId&&showLegacy.value))&&(!a.ownerId||a.ownerId===backend.user?.id))||[])
const {splitRegion,style:readerWidth,limits:readerLimits,width:readerPanelWidth,begin:resizeBegin,move:resizeMove,end:resizeEnd,keys:resizeKeys}=useAssistantWidth()
const readingRequest=ref<{id:number;operation:string}|null>(null),readerAssistant=ref<InstanceType<typeof ReaderAssistant>>()
const doc=ref<LocalDocument>(),loading=ref(true),error=ref(''),pageNumber=ref(1),scale=ref(1),rotation=ref(0),scrollArea=ref<HTMLElement>()
const activeTab=ref('notes'),saveState=ref('已保存在此浏览器'),comment=ref(''),commentInput=ref<HTMLTextAreaElement>(),color=ref('#B69AFF'),tool=ref<'select'|'region'>('select'),query=ref(''),searching=ref(false),exporting=ref(false)
const selection=ref<{quote:string;rects:number[][];page:number;anchor?:{left:number;right:number;top:number;bottom:number}}|null>(null)
const expandedNote=ref<string|null>(null)
const questionDraft=ref(false),editingId=ref<string|null>(null),editingComment=ref('')
const currentPaper=computed(()=>doc.value?store.papers.find(p=>p.localDocumentId===doc.value!.id&&store.sessions.find(s=>s.id===readerWorkspace.value)?.paperIds.includes(p.id)):undefined)
const navigation=ref(window.innerWidth>900),inspector=ref(true),outline=ref<{title:string;page:number;depth:number}[]>([]),pageLabels=ref<string[]>([]),indexedPages=ref<{page:number;text:string}[]>([]),indexing=ref(false),indexNotice=ref(''),versionNotice=ref(''),matches=ref<{page:number;snippet:string}[]>([]),focusHighlight=ref<Annotation|null>(null)
const layoutMenu=ref<HTMLDetailsElement>()
const layoutMode=computed(()=>!inspector.value?'focus':navigation.value?'full':'ai')
async function setLayout(mode:ReaderLayout){const state=readerLayoutState(mode),area=scrollArea.value,top=area?.scrollTop||0,left=area?.scrollLeft||0;ignoreScrollUntil=Date.now()+500;navigation.value=state.navigation;inspector.value=state.inspector;if(mode==='ai')activeTab.value='ai';if(layoutMenu.value)layoutMenu.value.open=false;await nextTick();if(area===scrollArea.value&&area){area.scrollTop=top;area.scrollLeft=left}}
function layoutOutside(e:PointerEvent){if(layoutMenu.value&&!layoutMenu.value.contains(e.target as Node))layoutMenu.value.open=false}
function layoutKey(e:KeyboardEvent){if(e.key==='Escape'&&layoutMenu.value?.open){layoutMenu.value.open=false;layoutMenu.value.querySelector('summary')?.focus()}}
let ignoreScrollUntil=0;let pdf:PDFDocumentProxy|undefined,disposed=false,loadGeneration=0,indexGeneration=0,scrollTimer:ReturnType<typeof setTimeout>|undefined,saveTimer:ReturnType<typeof setTimeout>|undefined,highlightTimer:ReturnType<typeof setTimeout>|undefined,saveChain=Promise.resolve()
async function persist(){if(!doc.value)return;const snapshot={...doc.value,annotations:JSON.parse(JSON.stringify(doc.value.annotations)),bookmarks:[...(doc.value.bookmarks||[])],lastPage:pageNumber.value,readingState:{scale:scale.value,rotation:rotation.value,openedAt:new Date().toISOString()}};saveState.value='正在保存…';saveChain=saveChain.catch(()=>{}).then(()=>saveDocument(snapshot));try{await saveChain;if(doc.value?.id===snapshot.id)saveState.value='已保存在此浏览器'}catch{saveState.value='保存失败，请重试';store.notify('阅读状态或批注尚未保存，请重试。')}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>void persist(),350)}
function go(page:number){if(!doc.value)return;ignoreScrollUntil=Date.now()+650;clearTimeout(scrollTimer);scrollTimer=undefined;pageNumber.value=Math.max(1,Math.min(doc.value.pageCount,Math.floor(page)||1));selection.value=null;void nextTick(()=>scrollArea.value?.querySelector<HTMLElement>('[data-page="'+pageNumber.value+'"]')?.scrollIntoView({block:'start',behavior:'instant'}));scheduleSave()}
function onScroll(){if(Date.now()<ignoreScrollUntil||scrollTimer)return;scrollTimer=setTimeout(()=>{scrollTimer=undefined;const area=scrollArea.value;if(!area)return;const pages=area.querySelectorAll<HTMLElement>('[data-page]'),top=area.getBoundingClientRect().top+area.clientHeight*.45;let lo=0,hi=pages.length-1,best=0;while(lo<=hi){const mid=(lo+hi)>>1;if(pages[mid]!.getBoundingClientRect().top<=top){best=mid;lo=mid+1}else hi=mid-1}if(pages[best]){pageNumber.value=Number(pages[best]!.dataset.page);scheduleSave()}},150)}
function choose(value:{quote:string;rects:number[][];page:number;anchor?:{left:number;right:number;top:number;bottom:number}}){questionDraft.value=false;selection.value=value;pageNumber.value=value.page;if(tool.value==='region'){tool.value='select';prepareComment()}}
async function bookmark(){if(!doc.value)return;const old=doc.value.bookmarks||[];doc.value.bookmarks=old.includes(pageNumber.value)?old.filter(p=>p!==pageNumber.value):[...old,pageNumber.value].sort((a,b)=>a-b);await persist()}
function annotationsFor(page:number){return [...(visibleAnnotations.value.filter(a=>a.page===page)||[]),...(focusHighlight.value?.page===page?[focusHighlight.value]:[])]}
function locateReading(source:ReadingRequest){if(source.documentId!==doc.value?.id||source.documentVersion!==doc.value?.hash){store.notify('来源属于不同文档版本，无法套用位置。');return}const a=source.evidence[0];if(!a){store.notify('这条记录没有可定位原文。');return}if(!Number.isInteger(a.pageIndex)||a.pageIndex<0||a.pageIndex>=doc.value.pageCount){store.notify('来源页序超出当前 PDF，无法精确定位。');return}go(a.pageIndex+1);if(a.rects.length){focusHighlight.value={id:'active-source',page:a.pageIndex+1,type:'highlight',quote:a.quote,comment:'阅读来源',rects:a.rects,color:'#F3CE83',createdAt:'',origin:'user'};clearTimeout(highlightTimer);highlightTimer=setTimeout(()=>focusHighlight.value=null,5000)}}
async function saveAi(value:{message:BackendMessage;source:ReadingRequest;conversationId:string;question:string}){if(value.source.documentId!==doc.value?.id||value.source.documentVersion!==doc.value.hash)return;if(doc.value.annotations.some(a=>a.runId===value.message.runId&&a.workspaceId===readerWorkspace.value&&a.ownerId===backend.user?.id)){store.notify('这条理解已保存，原笔记保留。');return}const source=value.source.evidence[0];doc.value.annotations.push({id:crypto.randomUUID(),page:source?source.pageIndex+1:pageNumber.value,type:'note',quote:source?.quote||'',comment:value.message.content,rects:source?.rects||[],color:color.value,createdAt:new Date().toISOString(),origin:'ai',runId:value.message.runId,documentVersion:doc.value.hash,conversationId:value.conversationId,messageId:value.message.id,question:value.question,paperId:currentPaper.value?.id,workspaceId:readerWorkspace.value,ownerId:backend.user?.id,readingSource:JSON.parse(JSON.stringify(value.source)),noteType:'ai'});await persist()}
function questionNote(text:string){questionDraft.value=true;comment.value=text;activeTab.value='notes';if(!selection.value)selection.value={quote:'',page:pageNumber.value,rects:[]};prepareComment()}
function annotationClicked(annotation:Annotation){expandedNote.value=annotation.id;editingId.value=null;activeTab.value='notes';inspector.value=true;go(annotation.page);void nextTick(()=>document.getElementById('annotation-'+annotation.id)?.scrollIntoView({block:'nearest'}))}
async function buildIndex(file:PDFDocumentProxy,n:number){indexing.value=true;indexNotice.value='正在建立本地页面文本索引…';const pages:{page:number;text:string}[]=[];let length=0,empty=0;try{for(let page=1;page<=file.numPages;page++){const p=await file.getPage(page),c=await p.getTextContent();if(disposed||n!==indexGeneration)return;const text=c.items.map(i=>'str' in i?i.str+('hasEOL' in i&&i.hasEOL?'\n':' '):'').join('').trim();length+=text.length;if(length>2000000){indexNotice.value='本地搜索索引达到 200 万字符上限，仅包含前 '+(page-1)+' 页。';break}if(!text)empty++;pages.push({page,text});if(page%10===0)indexedPages.value=[...pages]}if(n!==indexGeneration)return;indexedPages.value=pages;if(length<=2000000)indexNotice.value=empty?'有 '+empty+' 页未提取到文字；扫描页尚不支持 OCR。':'页面文字索引已就绪。双栏、公式和表格的阅读顺序及符号仍须核对 PDF 原图。';if(query.value)matches.value=findPageMatches(pages,query.value)}catch{if(n===indexGeneration)indexNotice.value='部分页面无法解析，仍可阅读原始 PDF。'}finally{if(n===indexGeneration)indexing.value=false}}
async function buildOutline(file:PDFDocumentProxy,n:number){try{const labels=await file.getPageLabels();if(n!==loadGeneration)return;pageLabels.value=labels||[];const items=await file.getOutline(),result:{title:string;page:number;depth:number}[]=[];async function visit(nodes:any[],depth=0){if(depth>6)return;for(const node of nodes){if(result.length>=500||n!==loadGeneration)return;try{const dest=typeof node.dest==='string'?await file.getDestination(node.dest):node.dest;if(Array.isArray(dest)&&dest[0]!=null){const page=typeof dest[0]==='number'?dest[0]:await file.getPageIndex(dest[0]);result.push({title:String(node.title),page:page+1,depth})}}catch{}if(node.items?.length)await visit(node.items,depth+1)}}await visit(items||[]);if(n===loadGeneration)outline.value=result}catch{}}
function editAnnotation(annotation:Annotation){expandedNote.value=annotation.id;editingId.value=annotation.id;editingComment.value=annotation.comment}
function toggleNote(id:string,event:Event){if((event.currentTarget as HTMLDetailsElement).open)expandedNote.value=id;else if(expandedNote.value===id)expandedNote.value=null}
async function saveAnnotation(){const annotation=doc.value?.annotations.find(a=>a.id===editingId.value);if(!annotation)return;annotation.comment=editingComment.value;await persist();editingId.value=null}
async function add(type:Annotation['type']){const chosen=selection.value;if(!chosen||!doc.value){store.notify('请先选择原文或框选一个区域。');return}doc.value.annotations.push({id:crypto.randomUUID(),page:chosen.page,type,quote:chosen.quote,comment:comment.value,rects:chosen.rects.map(r=>[...r]),color:color.value,createdAt:new Date().toISOString(),origin:'user',documentVersion:doc.value.hash,paperId:currentPaper.value?.id,workspaceId:readerWorkspace.value,ownerId:backend.user?.id,noteType:questionDraft.value?'question':comment.value?'understanding':'excerpt'});await persist();selection.value=null;questionDraft.value=false;comment.value='';window.getSelection()?.removeAllRanges();activeTab.value='notes'}
function prepareComment(){activeTab.value='notes';nextTick(()=>commentInput.value?.focus())}
function explain(operation='explain'){if(!selection.value)return;activeTab.value='ai';inspector.value=true;readingRequest.value={id:Date.now(),operation}}
function dismissSelection(){selection.value=null;window.getSelection()?.removeAllRanges()}
function selectionAction(action:string){if(action==='highlight'||action==='underline')void add(action);else if(action==='comment')prepareComment();else if(action==='excerpt')void add('note');else explain(action)}
async function search(){if(!query.value.trim())return;searching.value=true;try{matches.value=findPageMatches(indexedPages.value,query.value);if(matches.value.length)go(matches.value[0]!.page);else store.notify(indexing.value?'索引仍在建立，请稍后重试。':'未找到匹配文字；扫描页需要 OCR。')}finally{searching.value=false}}
async function exportPdf(){if(!doc.value||exporting.value)return;exporting.value=true;try{downloadBlob(await exportAnnotated({...doc.value,annotations:visibleAnnotations.value}),doc.value.name.replace(/\.pdf$/i,'')+'_批注.pdf','application/pdf');store.notify('已导出标准 PDF 批注，原文件保持不变。')}catch{store.notify('导出失败，请重试。当前批注仍保留在浏览器中。')}finally{exporting.value=false}}
function exportMarkdown(){if(!doc.value)return;const text='# '+doc.value.name+'\n\n'+visibleAnnotations.value.map(a=>`## PDF 第 ${a.page} 页\n\n> ${a.quote}\n\n${a.comment||'高亮标记'}\n\n来源：${a.origin==='ai'?'阅读提示':'人工批注'}\n`).join('\n');downloadBlob(text,doc.value.name+'.md','text/markdown;charset=utf-8')}
function fit(){const file=pdf,area=scrollArea.value,n=loadGeneration;if(!file||!area)return;void file.getPage(pageNumber.value).then(p=>{if(disposed||n!==loadGeneration||scrollArea.value!==area)return;const base=p.getViewport({scale:1,rotation:rotation.value});scale.value=Math.max(.35,Math.min(1.4,(area.clientWidth-48)/base.width))})}
async function openDocument(){if(route.query.workspace===undefined){await router.replace({query:{...route.query,workspace:store.activeId||'default'}});return}if(typeof route.query.workspace!=='string'||route.query.workspace.length>100){error.value='研究空间标识无效。';loading.value=false;return}readerWorkspace.value=route.query.workspace;if(readerWorkspace.value!=='default'&&!store.sessions.some(s=>s.id===readerWorkspace.value)){error.value='此研究空间不在当前浏览器中，请从原研究空间打开论文。';loading.value=false;return}if(readerWorkspace.value!=='default')store.loadSession(readerWorkspace.value);const n=++loadGeneration;++indexGeneration;readingRequest.value=null;showLegacy.value=false;selection.value=null;focusHighlight.value=null;loading.value=true;error.value='';outline.value=[];indexedPages.value=[];matches.value=[];versionNotice.value='';const previous=pdf;pdf=undefined;await nextTick();await previous?.destroy();try{const loaded=await getDocument(String(route.params.id));if(n!==loadGeneration||disposed)return;doc.value=loaded;if(!doc.value){error.value='这个文件不在当前浏览器中，请重新上传。';return}const file=await loadPdf({data:new Uint8Array(doc.value.bytes.slice(0)),isEvalSupported:false}).promise;if(disposed||n!==loadGeneration){await file.destroy();return}pdf=file;const state=doc.value.readingState;scale.value=state?Math.max(.35,Math.min(2.5,state.scale||1)):1;rotation.value=state&&[0,90,180,270].includes(state.rotation)?state.rotation:0;pageNumber.value=Math.max(1,Math.min(doc.value.lastPage||1,file.numPages));if(route.query.version&&route.query.version!==doc.value.hash)versionNotice.value='此引用的文档版本与当前文件不一致，未自动定位。';else if(route.query.page)pageNumber.value=Math.max(1,Math.min(file.numPages,Number(route.query.page)||1));loading.value=false;await nextTick();if(!state){const p=await file.getPage(pageNumber.value),v=p.getViewport({scale:1,rotation:rotation.value});scale.value=Math.max(.35,Math.min(1.4,((scrollArea.value?.clientWidth||800)-48)/v.width))}go(pageNumber.value);void buildOutline(file,n);void buildIndex(file,indexGeneration)}catch{if(n===loadGeneration)error.value='无法读取这份 PDF，请返回工作台重新上传。'}finally{if(n===loadGeneration)loading.value=false}}
onMounted(()=>{void openDocument();document.addEventListener('pointerdown',layoutOutside);document.addEventListener('keydown',layoutKey)})
watch(()=>[route.params.id,route.query.workspace],()=>void openDocument())
watch(()=>[route.query.page,route.query.version],()=>{if(!doc.value||loading.value)return;if(route.query.version&&route.query.version!==doc.value.hash){versionNotice.value='此引用的文档版本与当前文件不一致，未自动定位。';return}versionNotice.value='';if(route.query.page)go(Number(route.query.page))})
watch([scale,rotation],()=>{selection.value=null;if(!loading.value)go(pageNumber.value);else scheduleSave()})
onUnmounted(()=>{document.removeEventListener('pointerdown',layoutOutside);document.removeEventListener('keydown',layoutKey);disposed=true;++loadGeneration;++indexGeneration;clearTimeout(scrollTimer);clearTimeout(saveTimer);clearTimeout(highlightTimer);void persist();void pdf?.destroy()})
</script>
<template>
  <div class="reader-page"><header class="reader-header"><button class="icon-button" aria-label="返回研究空间" @click="router.push(readerWorkspace==='default'?'/chat':'/chat/'+readerWorkspace)"><Icon name="ArrowLeft"/></button><RouterLink to="/" aria-label="研迹首页"><Brand compact/></RouterLink><div class="reader-file-name"><strong>{{doc?.name||'文献阅读'}}</strong><span>{{doc?.demo?'原创体验材料 · 非已发表论文':'本地文献'}}<span>·</span>{{saveState}}</span></div><button class="icon-button" aria-label="切换阅读笔记与 AI 栏" :aria-pressed="inspector" @click="setLayout(inspector?'focus':navigation?'full':'ai')"><Icon name="PanelRightClose"/></button><button class="secondary-button" :disabled="!doc||exporting" :aria-busy="exporting" @click="exportPdf"><Icon :name="exporting?'LoaderCircle':'Download'" :class="{spin:exporting}" :size="15"/><span>导出带批注 PDF</span></button></header>
    <main id="main-content" ref="splitRegion" :style="readerWidth" class="reader-body"><aside v-if="navigation" class="reader-navigation" aria-label="论文导航"><div class="reader-paper-summary"><h2 :title="currentPaper?.title||doc?.name">{{currentPaper?.title||doc?.name||'论文导航'}}</h2><p class="settings-hint">{{compactAuthors(currentPaper?.authors)}}<span v-if="currentPaper?.year"> · {{currentPaper.year}}</span></p><p class="settings-hint">PDF 第 {{pageNumber}} / {{doc?.pageCount||'—'}} 页</p><details class="reader-paper-details"><summary>查看论文信息</summary><strong>{{currentPaper?.title||doc?.name}}</strong><p>{{currentPaper?.authors||'作者未提供'}}<span v-if="currentPaper?.year"> · {{currentPaper.year}}</span></p><p>{{doc?.name}} · {{doc?.pageCount||'—'}} 页</p></details></div><div class="reader-navigation-scroll"><h3>章节目录</h3><p v-if="!outline.length" class="settings-hint">文件未提供内置目录。可使用页码导航或原文搜索。</p><button v-for="(item,i) in outline" :key="i" class="reader-nav-item" :style="{paddingLeft:8+item.depth*12+'px'}" @click="go(item.page)">{{item.title}} <small>{{item.page}}</small></button><h3>书签</h3><button class="secondary-button" :disabled="!doc" @click="bookmark">{{doc?.bookmarks?.includes(pageNumber)?'移除当前页书签':'收藏当前页'}}</button><button v-for="p in doc?.bookmarks||[]" :key="p" class="reader-nav-item" @click="go(p)">PDF 第 {{p}} 页 {{pageLabels[p-1]?'· '+pageLabels[p-1]:''}}</button><h3>阅读笔记</h3><button class="text-button" @click="activeTab='notes';inspector=true">查看 {{visibleAnnotations.length||0}} 条批注</button><p class="settings-hint">{{indexNotice}}</p></div></aside><section class="pdf-column" aria-label="PDF 阅读器"><div class="pdf-toolbar"><details ref="layoutMenu" class="reader-layout-menu" @keydown="layoutKey"><summary aria-label="阅读布局" title="阅读布局"><Icon name="LayoutGrid" :size="17"/></summary><div role="group" aria-label="选择阅读布局"><button v-for="item in [{id:'full',label:'完整工作台'},{id:'ai',label:'AI 精读'},{id:'focus',label:'专注阅读'}]" :key="item.id" type="button" :aria-pressed="layoutMode===item.id" @click="setLayout(item.id as ReaderLayout)">{{item.label}}<Icon v-if="layoutMode===item.id" name="Check" :size="13"/></button></div></details><button class="icon-button" :aria-pressed="navigation" aria-label="切换论文导航" @click="setLayout(navigation?'ai':'full')"><Icon name="List"/></button><div><button class="icon-button" aria-label="上一页" :disabled="pageNumber<=1" @click="go(pageNumber-1)"><Icon name="ChevronLeft"/></button><label class="page-input"><span class="visually-hidden">PDF 页序</span><input type="number" min="1" :max="doc?.pageCount||1" :value="pageNumber" @change="go(Number(($event.target as HTMLInputElement).value))"/></label><span>/ {{doc?.pageCount||'—'}}</span><button class="icon-button" aria-label="下一页" :disabled="!doc||pageNumber>=doc.pageCount" @click="go(pageNumber+1)"><Icon name="ChevronRight"/></button></div><div><button class="icon-button" aria-label="缩小 PDF" @click="scale=Math.max(.35,scale-.15)"><Icon name="Minus" :size="16"/></button><button class="text-button zoom-label" aria-label="适应页面宽度" @click="fit">{{Math.round(scale*100)}}%</button><button class="icon-button" aria-label="放大 PDF" @click="scale=Math.min(2.5,scale+.15)"><Icon name="Plus" :size="16"/></button><button class="icon-button" aria-label="旋转 PDF 页面" @click="rotation=(rotation+90)%360"><Icon name="RotateCw" :size="16"/></button></div><button class="icon-button" :class="{selected:tool==='region'}" aria-label="框选区域添加评论" title="框选区域评论" @click="tool=tool==='region'?'select':'region'"><Icon name="Focus" :size="17"/></button></div>
      <div v-if="error" class="empty-state"><Icon name="FileText" :size="38"/><h1>文献暂时无法打开</h1><p>{{error}}</p><button class="primary-button" @click="store.uploadOpen=true">重新上传文献</button></div><div v-else-if="loading" class="empty-state"><Icon name="LoaderCircle" class="spin" :size="28"/><p>正在本地打开 PDF…</p></div>
      <p v-if="versionNotice" class="form-error" role="alert">{{versionNotice}}</p><div v-if="!loading&&!error&&pdf" ref="scrollArea" class="pdf-scroll-area" @scroll.passive="onScroll"><PdfPage v-for="p in doc?.pageCount||0" :key="doc!.id+':'+p" :pdf="pdf" :page="p" :scale="scale" :rotation="rotation" :annotations="annotationsFor(p)" :region-mode="tool==='region'&&p===pageNumber" @selection="choose" @warning="store.notify" @annotation="annotationClicked"/></div>
      <SelectionToolbar v-if="selection?.quote.trim()" :selection="selection" :container="scrollArea" @dismiss="dismissSelection" @action="selectionAction"/>
    </section>
    <div v-show="inspector" class="reader-resizer" role="separator" tabindex="0" aria-label="调整阅读助手宽度" aria-orientation="vertical" :aria-valuemin="readerLimits.min" :aria-valuemax="readerLimits.max" :aria-valuenow="readerPanelWidth||344" @pointerdown="resizeBegin" @pointermove="resizeMove" @pointerup="resizeEnd" @pointercancel="resizeEnd" @keydown="resizeKeys"></div><aside v-show="inspector" class="reader-inspector"><div class="detail-tabs"><button :class="{active:activeTab==='notes'}" @click="activeTab='notes'"><Icon name="Highlighter" :size="15"/>批注<span>{{visibleAnnotations.length||0}}</span></button><button :class="{active:activeTab==='ai'}" @click="activeTab='ai'"><Icon name="Sparkles" :size="15"/>AI 阅读</button></div>
      <form v-show="activeTab==='notes'" class="pdf-find" @submit.prevent="search"><label for="pdf-query" class="visually-hidden">搜索 PDF 原文</label><Icon name="Search" :size="15"/><input id="pdf-query" v-model="query" placeholder="搜索原文中的文字"/><button class="icon-button" :disabled="searching||!query.trim()" aria-label="搜索文献内容"><Icon :name="searching?'LoaderCircle':'ArrowRight'" :class="{spin:searching}" :size="15"/></button></form>
      <div v-if="matches.length&&activeTab==='notes'" class="reader-search-results"><span>{{matches.length}} 页匹配</span><button v-for="hit in matches" :key="hit.page" class="reader-nav-item" @click="go(hit.page)">PDF 第 {{hit.page}} 页 · {{hit.snippet}}</button></div><div v-if="activeTab==='notes'" class="annotation-list"><button v-if="legacyAnnotations.length" class="text-button" @click="showLegacy=!showLegacy">{{showLegacy?'收起':'查看'}} {{legacyAnnotations.length}} 条空间归属未确认的旧批注</button><div v-if="selection" class="new-comment"><span class="section-mini-label">PDF 第 {{selection.page}} 页 · {{selection.quote?'当前选区':'页级笔记，未引用原文'}}</span><blockquote v-if="selection.quote">{{selection.quote.slice(0,250)}}</blockquote><label for="annotation-comment">留下你的思考</label><textarea id="annotation-comment" ref="commentInput" v-model="comment" rows="4" placeholder="这段内容对我的研究有什么启发？"></textarea><div class="annotation-color-row"><button v-for="c in ['#B69AFF','#70D8BE','#F3CE83','#F0A0B3']" :key="c" class="color-choice" :class="{chosen:color===c}" :style="{background:c}" :aria-label="`使用批注颜色 ${c}`" :aria-pressed="color===c" @click="color=c"></button><button class="primary-button" :disabled="!comment.trim()" @click="add('note')">保存评论</button></div></div>
        <div v-if="!visibleAnnotations.length&&!selection" class="annotation-empty"><span class="feature-icon violet"><Icon name="Highlighter" :size="25"/></span><h2>让思考留在原文旁。</h2><p>选中一段文字，就能高亮、划线、评论，或向 AI 提问。</p><button class="secondary-button" @click="tool='region';store.notify('在页面上拖出一个区域，然后填写评论。')"><Icon name="Focus" :size="15"/>也可以框选区域</button><small>批注仅保存在此浏览器中。</small></div>
        <article v-for="annotation in visibleAnnotations" :key="annotation.id" :id="'annotation-'+annotation.id" class="annotation-card"><header><button class="text-button" @click="go(annotation.page)">第 {{annotation.page}} 页<Icon name="ArrowUpRight" :size="12"/></button><span>{{annotation.origin==='ai'?'AI 理解':annotation.noteType==='question'?'未解决的问题':'我的批注'}}</span><div class="annotation-actions"><button class="icon-button" aria-label="编辑这条批注" @click="editAnnotation(annotation)"><Icon name="Pencil" :size="13"/></button><button class="icon-button" aria-label="删除这条批注" @click="doc!.annotations=doc!.annotations.filter(a=>a.id!==annotation.id);persist()"><Icon name="Trash2" :size="13"/></button></div></header><p class="annotation-preview">{{annotation.comment||annotation.quote||'原文标记'}}</p><time v-if="annotation.createdAt" class="annotation-date" :datetime="annotation.createdAt">{{new Date(annotation.createdAt).toLocaleDateString('zh-CN')}}</time><details class="annotation-detail" :open="expandedNote===annotation.id" @toggle="toggleNote(annotation.id,$event)"><summary>查看详情</summary><blockquote v-if="annotation.quote" :style="{borderColor:annotation.color}">{{annotation.quote}}</blockquote><div v-if="editingId===annotation.id" class="annotation-edit"><label :for="'edit-'+annotation.id">修改批注内容</label><textarea :id="'edit-'+annotation.id" v-model="editingComment" rows="3" maxlength="4000"></textarea><div><button class="text-button" @click="editingId=null">取消</button><button class="primary-button" @click="saveAnnotation">保存修改</button></div></div><template v-else-if="annotation.comment"><Markdown v-if="annotation.origin==='ai'" :text="annotation.comment"/><p v-else>{{annotation.comment}}</p></template><small v-if="annotation.question">原始问题：{{annotation.question}}</small></details><div class="annotation-links"><button class="text-button" @click="annotation.readingSource?.evidence.length?locateReading(annotation.readingSource):go(annotation.page)">定位原文</button><button v-if="annotation.conversationId" class="text-button" @click="activeTab='ai';nextTick(()=>readerAssistant?.openLinkedConversation(annotation.conversationId!))">继续提问</button></div></article>
      </div>
      <ReaderAssistant v-if="doc&&!loading" v-show="activeTab==='ai'" ref="readerAssistant" :key="doc.id+':'+readerWorkspace" :workspace-id="readerWorkspace" :doc="doc" :page="pageNumber" :pages="indexedPages" :selection="selection" :request="readingRequest" @locate="locateReading" @save="saveAi" @question="questionNote"/>
      <footer v-show="activeTab==='notes'" class="reader-inspector-footer"><button class="text-button" :disabled="!visibleAnnotations.length" @click="exportMarkdown"><Icon name="Download" :size="14"/>导出批注 Markdown</button><button v-if="saveState.includes('失败')" class="text-button" @click="persist">重试保存</button></footer>
    </aside></main>
  </div>
</template>

